create table if not exists public.saved_searches(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,query text not null,scope text not null default 'all',filters jsonb not null default '{}'::jsonb,is_active boolean not null default true,created_at timestamptz not null default now(),unique(user_id,query,scope));
create table if not exists public.offers(id uuid primary key default gen_random_uuid(),conversation_id uuid not null,created_by uuid not null references auth.users(id) on delete cascade,amount numeric(12,2) not null check(amount>0),status text not null default 'pending' check(status in ('pending','accepted','rejected','countered','cancelled')),parent_offer_id uuid references public.offers(id) on delete set null,created_at timestamptz not null default now());
alter table public.saved_searches enable row level security;alter table public.offers enable row level security;
drop policy if exists "saved searches own" on public.saved_searches;create policy "saved searches own" on public.saved_searches for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
drop policy if exists "offers authenticated read" on public.offers;create policy "offers authenticated read" on public.offers for select to authenticated using(true);
drop policy if exists "offers own insert" on public.offers;create policy "offers own insert" on public.offers for insert to authenticated with check(auth.uid()=created_by);
alter table if exists public.wanted_posts add column if not exists max_price numeric(12,2) check(max_price is null or max_price>=0);
